# minority color per row. Demo: rows with 3-minority have run of 2s from some col to end changed to 1; other rows keep. So the rule is: in each row, identify the minority color's run(s); replace only the RIGHTMOST contiguous run of the minority color (which reaches right edge). Let me test that.
def f(g):
    h,w=len(g),len(g[0])
    res=[row[:] for row in g]
    for r in range(h):
        c=Counter(res[r])
        m=min(c,key=c.get)
        # find runs of m; take the one whose last cell is w-1
        i=0
        while i<w:
            if res[r][i]==m:
                j=i+1
                while j<w and res[r][j]==m: j+=1
                if j-1==w-1:
                    for k in range(i,j): res[r][k]=1
                i=j
            else: i+=1
    return res
